package ca.yorku.eecs3311.coursepilot.web; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/courses/{courseId}/agent") public class AgentController {private final StudyAgentFacade facade;public AgentController(StudyAgentFacade f){facade=f;}@GetMapping public String page(@PathVariable Long courseId,Model m){m.addAttribute("course",facade.getCourse(courseId));m.addAttribute("activeNav","agent");return "agent/index";}@PostMapping public String ask(@PathVariable Long courseId,@RequestParam String request,Model m){m.addAttribute("course",facade.getCourse(courseId));m.addAttribute("request",request);try{m.addAttribute("agentResult",facade.agentAssist(courseId,request));}catch(RuntimeException e){m.addAttribute("agentError",e.getMessage());}m.addAttribute("activeNav","agent");return "agent/index";}}
